def build_agent(sandbox):
    beam_w = 0.6  # Width of beams (0.15–2.0 m)
    beam_h = 0.4  # Height of beams (0.15–2.0 m)
    y_center = 1.4  # Safe y-position to avoid pillars

    # Beam positions: 5 beams spaced 1.5m apart, starting at x=2.0m
    centers_x = [2.0 + i * 1.5 for i in range(5)]
    bodies = []

    # Varying densities: front beams (0,1,2) have lower density, rear (3,4) higher
    for idx, x in enumerate(centers_x):
        if idx < 3:
            density = 15.0  # Lower density for front beams
        else:
            density = 25.0  # Higher density for rear beams to lower center of mass
        b = sandbox.add_beam(x, y_center, beam_w, beam_h, angle=0, density=density)
        sandbox.set_material_properties(b, restitution=0.05)
        bodies.append(b)

    # Connect beams with rigid joints
    for i in range(4):
        anchor_x = (centers_x[i] + centers_x[i + 1]) / 2
        sandbox.add_joint(bodies[i], bodies[i + 1], (anchor_x, y_center), type='rigid')

    return bodies[-1]

def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0

    if front_x >= target_x + 0.1:
        # Stop all motion upon reaching target
        for b in sandbox.bodies:
            if b.active:
                b.linearVelocity = (0, 0)
                b.angularVelocity = 0
        return

    # Track last thrust step for each body
    if not hasattr(agent_action, 'last_thrust_step'):
        agent_action.last_thrust_step = {body: -float('inf') for body in sandbox.bodies}

    # Apply thrust to rear beams first for reduced joint stress
    for body in reversed(sandbox.bodies):
        if step_count >= agent_action.last_thrust_step[body] + 3:
            THRUST_F = 520.0
            LIFT_F = 400.0  # Lift force for deep channel

            # Check if in deep channel
            in_deep_channel = (16.5 <= front_x <= 19.5)

            # Adjust thrust based on velocity
            vx = body.linearVelocity.x
            if vx > 1.8:
                fx = THRUST_F * 0.1
            elif vx > 1.0:
                fx = THRUST_F * 0.4
            else:
                fx = THRUST_F

            # Apply lift force in deep channel
            fy = LIFT_F if in_deep_channel else 0.0

            sandbox.apply_force(body, fx, fy, step_count=step_count)
            agent_action.last_thrust_step[body] = step_count
